  adoption_at TIMESTAMPTZ,
  baseline_value NUMERIC,
  campaign TEXT,
  delta_from_baseline NUMERIC,
  evaluation_mode TEXT,
  evaluator_digest TEXT,
  evidence_cutoff TIMESTAMPTZ,
  evidence_link TEXT,
  experiment TEXT,
  id TEXT NOT NULL CHECK (id <> ''),
  maturity_at TIMESTAMPTZ,
  maturity_status TEXT,
  observation_id TEXT,
  operational_case TEXT,
  operational_value_direction TEXT,
  operational_value_name TEXT,
  operational_value_role TEXT,
  operational_value_unit TEXT,
  repository_id TEXT NOT NULL,
  requested_evidence_at TIMESTAMPTZ,
  rollout_mode TEXT,
  rollup_denominator NUMERIC,
  rollup_numerator NUMERIC,
  run TEXT,
  run_attempt NUMERIC,
  run_link TEXT,
  timestamp TIMESTAMPTZ,
  value NUMERIC,
  value_id TEXT,
  workflow TEXT,
  workflow_link TEXT,
  workflow_name TEXT,
  workflow_slug TEXT,

  PRIMARY KEY (namespace, id),
  UNIQUE (namespace, ordinal),
  CHECK (bit_length(present_fields) = 33),
  FOREIGN KEY (namespace) REFERENCES cao_state(namespace) ON DELETE CASCADE,
  CHECK (repository_id IS NOT NULL AND repository_id <> ''),
  FOREIGN KEY (namespace, repository_id) REFERENCES repositories(namespace, id) DEFERRABLE INITIALLY DEFERRED
);

CREATE INDEX IF NOT EXISTS operational_values_repository_id ON operational_values (namespace, repository_id, ordinal);

