CREATE TABLE IF NOT EXISTS skills (
  namespace TEXT NOT NULL,
  ordinal BIGINT NOT NULL CHECK (ordinal >= 0),
  present_fields BIT VARYING NOT NULL,
  activation_source TEXT,
  correlation_id TEXT,
  failed_count BIGINT,
  id TEXT NOT NULL CHECK (id <> ''),
  invocation_count BIGINT,
  name TEXT,
  observed_at TIMESTAMPTZ,
  payload_ref TEXT,
  run_id TEXT NOT NULL,
  source TEXT,
  source_sequence BIGINT,
  status TEXT,
  summary TEXT,
  timestamp TIMESTAMPTZ,
  tool_type TEXT,
  type TEXT,
  run_at TIMESTAMPTZ NOT NULL,

  PRIMARY KEY (namespace, id, run_at),
  UNIQUE (namespace, ordinal, run_at),
  CHECK (bit_length(present_fields) = 16),
  FOREIGN KEY (namespace) REFERENCES cao_state(namespace) ON DELETE CASCADE,
  CHECK (run_id IS NOT NULL AND run_id <> ''),
  FOREIGN KEY (namespace, run_id, run_at) REFERENCES runs(namespace, id, run_at) DEFERRABLE INITIALLY DEFERRED
) PARTITION BY RANGE (run_at);

CREATE INDEX IF NOT EXISTS skills_run_id ON skills (namespace, run_id, ordinal);

CREATE INDEX IF NOT EXISTS skills_identity ON skills (namespace, id);

CREATE TABLE IF NOT EXISTS tool_identities (
  namespace TEXT NOT NULL,
  ordinal BIGINT NOT NULL CHECK (ordinal >= 0),
  present_fields BIT VARYING NOT NULL,
  id TEXT NOT NULL CHECK (id <> ''),
  mcp_protocol_version TEXT,
  mcp_server TEXT,
  mcp_server_version TEXT,
  mcp_tool TEXT,
  name TEXT,
  observed_at TIMESTAMPTZ NOT NULL,
  tool_type TEXT,

  PRIMARY KEY (namespace, id),
  UNIQUE (namespace, ordinal),
  CHECK (bit_length(present_fields) = 8),
  FOREIGN KEY (namespace) REFERENCES cao_state(namespace) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS tools (
  namespace TEXT NOT NULL,
  ordinal BIGINT NOT NULL CHECK (ordinal >= 0),
  present_fields BIT VARYING NOT NULL,
  evidence_revision TEXT NOT NULL,
  ambiguous_count BIGINT NOT NULL,
  call_count BIGINT NOT NULL,
  event_count BIGINT NOT NULL,
  failed_count BIGINT NOT NULL,
  id TEXT NOT NULL CHECK (id <> ''),
  incomplete_count BIGINT NOT NULL,
  latency_count BIGINT NOT NULL,
  latency_max NUMERIC,
  latency_min NUMERIC,
  latency_sum NUMERIC NOT NULL,
  observed_at TIMESTAMPTZ NOT NULL,
  outcome_count BIGINT NOT NULL,
  request_bytes BIGINT NOT NULL,
  request_bytes_count BIGINT NOT NULL,
  response_bytes BIGINT NOT NULL,
  response_bytes_count BIGINT NOT NULL,
  run_id TEXT NOT NULL,
  sample_call_id TEXT,
  sample_outcome_id TEXT,
  source TEXT NOT NULL,
  success_count BIGINT NOT NULL,
  timestamp TIMESTAMPTZ NOT NULL,
  last_timestamp TIMESTAMPTZ NOT NULL,
  tool_id TEXT NOT NULL,
  unknown_outcome_count BIGINT NOT NULL,
  unmatched_count BIGINT NOT NULL,
  run_at TIMESTAMPTZ NOT NULL,

  PRIMARY KEY (namespace, id, run_at),
  UNIQUE (namespace, ordinal, run_at),
  CHECK (bit_length(present_fields) = 27),
  FOREIGN KEY (namespace) REFERENCES cao_state(namespace) ON DELETE CASCADE,
  UNIQUE (namespace, run_id, tool_id, source, run_at),
  CHECK (run_id IS NOT NULL AND run_id <> ''),
  FOREIGN KEY (namespace, run_id, run_at) REFERENCES runs(namespace, id, run_at) DEFERRABLE INITIALLY DEFERRED,
  CHECK (tool_id IS NOT NULL AND tool_id <> ''),
  FOREIGN KEY (namespace, tool_id) REFERENCES tool_identities(namespace, id) DEFERRABLE INITIALLY DEFERRED
) PARTITION BY RANGE (run_at);

CREATE INDEX IF NOT EXISTS tools_run_id ON tools (namespace, run_id, ordinal);

CREATE INDEX IF NOT EXISTS tools_tool_id ON tools (namespace, tool_id, ordinal);

CREATE TABLE IF NOT EXISTS tool_counters (
  namespace TEXT NOT NULL,
  ordinal BIGINT NOT NULL CHECK (ordinal >= 0),
  present_fields BIT VARYING NOT NULL,
  evidence_revision TEXT NOT NULL,
  event_count BIGINT NOT NULL,
  id TEXT NOT NULL CHECK (id <> ''),
  timestamp TIMESTAMPTZ NOT NULL,
  last_timestamp TIMESTAMPTZ NOT NULL,
  observed_at TIMESTAMPTZ NOT NULL,
  request_bytes BIGINT NOT NULL,
  request_bytes_count BIGINT NOT NULL,
  response_bytes BIGINT NOT NULL,
  response_bytes_count BIGINT NOT NULL,
  run_id TEXT NOT NULL,
  usage_id TEXT NOT NULL,
  status TEXT,
  type TEXT,
  run_at TIMESTAMPTZ NOT NULL,

  PRIMARY KEY (namespace, id, run_at),
  UNIQUE (namespace, ordinal, run_at),
  CHECK (bit_length(present_fields) = 14),
  FOREIGN KEY (namespace) REFERENCES cao_state(namespace) ON DELETE CASCADE,
  CHECK (run_id IS NOT NULL AND run_id <> ''),
  FOREIGN KEY (namespace, run_id, run_at) REFERENCES runs(namespace, id, run_at) DEFERRABLE INITIALLY DEFERRED,
  CHECK (usage_id IS NOT NULL AND usage_id <> ''),
  FOREIGN KEY (namespace, usage_id, run_at) REFERENCES tools(namespace, id, run_at) DEFERRABLE INITIALLY DEFERRED
) PARTITION BY RANGE (run_at);

CREATE INDEX IF NOT EXISTS tool_counters_run_id ON tool_counters (namespace, run_id, ordinal);

CREATE INDEX IF NOT EXISTS tool_counters_usage_id ON tool_counters (namespace, usage_id, ordinal);

